<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/app.php';
function publicCount(PDO $pdo, string $table): int { if (!in_array($table, ['books', 'categories', 'users'], true)) { return 0; } return (int) $pdo->query('SELECT COUNT(*) FROM `' . $table . '`')->fetchColumn(); }
$totalBooks = publicCount($pdo, 'books'); $totalCategories = publicCount($pdo, 'categories'); $totalUsers = publicCount($pdo, 'users');
$categoryStats = $pdo->query('SELECT categories.name, COUNT(books.id) AS total FROM categories LEFT JOIN books ON books.category_id = categories.id GROUP BY categories.id, categories.name ORDER BY total DESC, categories.name')->fetchAll();
$recentBooks = $pdo->query('SELECT title, author FROM books ORDER BY id DESC LIMIT 5')->fetchAll();
$pageTitle = 'الإحصائيات'; $activePage = 'stats'; require __DIR__ . '/includes/header.php';
?>
<section class="page-intro"><div class="container"><p class="eyebrow">صورة من المكتبة</p><h1>الإحصائيات</h1><p>نظرة عامة على الكتب والتصنيفات ومجتمع القراء.</p></div></section><section class="section"><div class="container"><div class="stats-grid"><article class="stat-card"><span>إجمالي الكتب</span><strong><?= number_format($totalBooks) ?></strong></article><article class="stat-card"><span>التصنيفات</span><strong><?= number_format($totalCategories) ?></strong></article><article class="stat-card"><span>القراء المسجلون</span><strong><?= number_format($totalUsers) ?></strong></article></div><div class="charts-grid"><section class="chart-panel"><h2>توزيع الكتب حسب التصنيف</h2><canvas id="categoryChart" aria-label="رسم توزيع الكتب حسب التصنيف"></canvas></section><section class="chart-panel"><h2>آخر الكتب المضافة</h2><?php if (!$recentBooks): ?><p class="book-author">لا توجد كتب بعد.</p><?php endif; ?><?php foreach ($recentBooks as $book): ?><div style="padding:11px 0;border-bottom:1px solid var(--line)"><strong><?= e($book['title']) ?></strong><div class="book-author"><?= e($book['author']) ?></div></div><?php endforeach; ?></section></div></div></section><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const categoryLabels = <?= json_encode(array_column($categoryStats, 'name'), JSON_UNESCAPED_UNICODE) ?>; const categoryValues = <?= json_encode(array_map('intval', array_column($categoryStats, 'total'))) ?>; new Chart(document.getElementById('categoryChart'), {type:'doughnut',data:{labels:categoryLabels,datasets:[{data:categoryValues,backgroundColor:['#173f3a','#c47b55','#7aa49a','#d6a57f','#9ab8ae','#e7c9b7']}]},options:{responsive:true,plugins:{legend:{position:'bottom',labels:{font:{family:'IBM Plex Sans Arabic'}}}}}});</script>
<?php require __DIR__ . '/includes/footer.php'; ?>